import ast
import inspect

# Parse key files for detailed function signatures
files_to_analyze = [
    ('/app/black/src/black/__init__.py', 'Main Formatter API'),
    ('/app/black/src/black/strings.py', 'String Processing'),
    ('/app/black/src/black/parsing.py', 'Parsing Functions'),
]

for filepath, title in files_to_analyze:
    print(f"\n=== {title} ===")
    with open(filepath, 'r') as f:
        tree = ast.parse(f.read())

    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and not node.name.startswith('_'):
            # Get signature
            args = []
            for arg in node.args.args:
                args.append(arg.arg)

            # Get return type if available
            returns = "-> unknown"
            if node.returns:
                returns = ast.unparse(node.returns)

            print(f"  {node.name}({', '.join(args[:3])}{'...' if len(args) > 3 else ''}) {returns}")
        elif isinstance(node, ast.ClassDef) and not node.name.startswith('_'):
            print(f"  class {node.name}:")
            # Get init signature if available
            for item in node.body:
                if isinstance(item, ast.FunctionDef) and item.name == '__init__':
                    args = [a.arg for a in item.args.args if a.arg != 'self']
                    if args:
                        print(f"    __init__({', '.join(args[:2])}{'...' if len(args) > 2 else ''})")
EOF
